<?php namespace App\Filament\Resources\CuratorPlanResource\RelationManagers;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\RelationManagers\RelationManager;use Filament\Resources\Table;use Filament\Tables;class ItemsRelationManager extends RelationManager{protected static string $relationship='items';protected static ?string $title='Мероприятия плана';public static function form(Form $f):Form{return $f->schema([Forms\Components\DatePicker::make('planned_on')->label('Дата'),Forms\Components\TextInput::make('direction')->label('Направление')->required(),Forms\Components\TextInput::make('title')->label('Мероприятие')->required(),Forms\Components\Select::make('status')->label('Статус')->options(['planned'=>'Запланировано','done'=>'Выполнено','cancelled'=>'Отменено'])->default('planned'),Forms\Components\Textarea::make('result')->label('Результат')]);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('planned_on')->label('Дата')->date('d.m.Y'),Tables\Columns\TextColumn::make('direction')->label('Направление'),Tables\Columns\TextColumn::make('title')->label('Мероприятие'),Tables\Columns\BadgeColumn::make('status')->label('Статус')])->headerActions([Tables\Actions\CreateAction::make()->label('Добавить пункт')])->actions([Tables\Actions\EditAction::make(),Tables\Actions\DeleteAction::make()]);}}